$(document).ready(function(e){if($(".selectJS").length){function t(e){if(!e.id)return e.text;var t=$(e.element).data("flag"),n=$(`<div style="display: flex; align-items: center; padding: 5px;">\n          <img src="${t}" style="width: 30px; height: 30px; border-radius: 50%; margin-right: 10px;" />\n          <span>${e.text}</span>\n        </div>`);return n}$(".selectJS").select2({placeholder:"Search for country",templateResult:t,tag:!0,templateSelection:t,width:"100%"})}});